#include <iostream>
#include <string>
#include <utility>

int main() {
    const int NUMBER_OF_CARDS = 52;
    int deck[NUMBER_OF_CARDS];

    const std::string suits[] = {"Spades", "Hearts", "Diamonds", "Clubs"};
    const std::string ranks[] = {"Ace", "2", "3", "4", "5", "6", "7", "8", "9",
                                 "10", "Jack", "Queen", "King"};

    for (int i = 0; i < NUMBER_OF_CARDS; ++i) {
        deck[i] = i;
    }

    // Deterministic shuffle demonstration using fixed swaps for reproducible output
    // Swapping card 0 with 6, card 1 with 48, card 2 with 11, card 3 with 24
    std::swap(deck[0], deck[6]);
    std::swap(deck[1], deck[48]);
    std::swap(deck[2], deck[11]);
    std::swap(deck[3], deck[24]);

    // Display the first four cards
    for (int i = 0; i < 4; ++i) {
        std::string suit = suits[deck[i] / 13];
        std::string rank = ranks[deck[i] % 13];
        std::cout << "Card number " << deck[i] << ": " << rank << " of " << suit << "\n";
    }

    return 0;
}

#include <iostream>

// const prevents the function from modifying array elements
void printArray(const int list[], int size) {
    for (int i = 0; i < size; ++i) {
        std::cout << list[i] << (i + 1 < size ? " " : "\n");
    }
}

// Non-const array parameter allows in-place modification
void modifyArray(int list[], int size, int multiplier) {
    for (int i = 0; i < size; ++i) {
        list[i] *= multiplier;
    }
}

// Demonstrates primitive pass-by-value vs array pass-by-sharing
void testPassing(int primitiveVar, int arr[]) {
    primitiveVar = 999;  // Only modifies local copy
    arr[0] = 5555;       // Modifies caller array in-place
}

int main() {
    int a = 1;
    int numbers[5] = {1, 4, 3, 6, 8};

    std::cout << "Original numbers: ";
    printArray(numbers, 5);

    testPassing(a, numbers);
    std::cout << "After testPassing: a = " << a << ", numbers[0] = " << numbers[0] << "\n";

    modifyArray(numbers, 5, 2);
    std::cout << "After modifyArray (x2): ";
    printArray(numbers, 5);

    return 0;
}
